const items = $input.all();
const newItems = [];

for (let item of items) {
  const htmlContent = item.json.data || "";

  const titleMatch = htmlContent.match(/<title>([^<]+)<\/title>/);
  let rawTitle = titleMatch ? titleMatch[1] : "empty";

  const cleanTitle = rawTitle
    .split(/&#8211;|–|-/)[0]
    .replace(/&#8217;|&#8216;|&rsquo;|&lsquo;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/&#\d+;/g, "")
    .trim();

  const viewMatch = htmlContent.match(/class="post-views-count"[^>]*>(\d+)</);
  const nodeValue = viewMatch ? parseInt(viewMatch[1], 10) : null;

  if (nodeValue !== null && nodeValue > 300) {
    newItems.push({
      json: {
        postId: item.json.id || null,
        title: cleanTitle,
        nodeValue: nodeValue
      }
    });
  }
}

return newItems;

const items = $input.all();

function extractId(item) {
  if (!item || !item.json) return null;

  const keys = Object.keys(item.json);
  const idKey = keys.find(k => k.trim().toLowerCase() === 'id');

  if (idKey && item.json[idKey] !== undefined && item.json[idKey] !== null) {
    return String(item.json[idKey]).trim();
  }

  return null;
}

const allIds = items
  .map(item => extractId(item))
  .filter(id => id !== null && id !== '');

const idsText = allIds.join(', ');

return [
  {
    json: {
      all_ids_text: idsText,
      total_rows: allIds.length
    }
  }
];

return $input.all().map(item => {
    let rawContent = '';
    if (typeof item.json.post_content === 'object' && item.json.post_content !== null) {
        rawContent = item.json.post_content.rendered || '';
    } else {
        rawContent = item.json.post_content || item.json.content || '';
    }

    const allHtml = item.json.all_html || '';
    let imageUrl = item.json.extracted_img_url || '';

    if ((!imageUrl || !imageUrl.startsWith('http')) && allHtml) {
        const imgMatch = allHtml.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (imgMatch) {
            imageUrl = imgMatch[1];
        }
    }

    const imgTag = imageUrl ? `<p><img src="${imageUrl}" class="aligncenter size-full" /></p>\n` : '';

    let cleanContent = rawContent.replace(/<ins[^>]*>[\s\S]*?<\/ins>/gi, '').trim();

    const paragraphs = cleanContent.split(/(<\/p>|\n)/i);

    let formattedContent = '';
    let currentLength = 0;
    let pageCount = 1;
    const maxChars = 2000;

    if (imgTag && !cleanContent.includes(imageUrl)) {
        formattedContent += imgTag;
    }

    for (let i = 0; i < paragraphs.length; i++) {
        let chunk = paragraphs[i];
        formattedContent += chunk;
        currentLength += chunk.length;

        if (currentLength >= maxChars && (chunk.includes('</p>') || chunk.includes('.'))) {
            if (i < paragraphs.length - 1) {
                formattedContent += `\n<!--nextpage-->\n${imgTag}`;
                currentLength = 0; 
                pageCount++;
            }
        }
    }

    return {
        json: {
            ...item.json,
            test_dev: formattedContent,
            total_pages: pageCount
        }
    };
});

