function fixTitleEntities(text) {
  if (!text) return '';

  return String(text)
    .replace(/&#8230;/g, '…')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&#(\d+);/g, (match, dec) =>
      String.fromCharCode(dec));
}

for (const item of $input.all()) {
  if (item.json.title) {
    item.json.title = fixTitleEntities(item.json.title);
  }
}

return $input.all();

