const posts = $('Merge13').all();

const idsData = $('filter2').first()?.json || {};
const idsText = String(idsData.all_ids_text || '');

const existingIds = new Set(
  idsText
    .split(',')
    .map(id => id.trim())
    .filter(Boolean)
);

const filteredPosts = posts.filter(post => {
  const pId = String(post.json?.id || post.json?.ID || '').trim();

  if (!pId) return false;

  return !existingIds.has(pId);
});

return filteredPosts;

