const items = $input.all();
const originalPosts = $('only 15 items2').all();

return items.map((item, index) => {
  const html = item.json.data || '';
  const post = originalPosts[index]?.json || {};

  const ogMatch = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) 
               || html.match(/<meta[^>]+content=["']([^"']+)["']+property=["']og:image["']/i);
  const imgMatch = html.match(/<img[^>]+src=["']([^"']+)["']/i);
  const foundImage = ogMatch ? ogMatch[1] : (imgMatch ? imgMatch[1] : '');

  let fullArticleHtml = '';

  const articleContentMatch = html.match(/<article[^>]*>([\s\S]*?)<\/article>/i)
                           || html.match(/<div[^>]+class=["'][^"']*(?:entry-content|post-content|article-body)[^"']*["'][^>]*>([\s\S]*?)<\/div>/i);

  if (articleContentMatch) {
    fullArticleHtml = articleContentMatch[1];
  } else {
    const extractedBlocks = html.match(/<(p|h1|h2|h3|h4|div class="entry-content")[^>]*>[\s\S]*?<\/\1>/gi) || [];
    fullArticleHtml = extractedBlocks.join('\n');
  }

  fullArticleHtml = fullArticleHtml
    .replace(/<ins[^>]*>[\s\S]*?<\/ins>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<iframe[^>]*>[\s\S]*?<\/iframe>/gi, '')
    .replace(/<div[^>]+class=["'][^"']*google-anno[^"']*["'][^>]*>[\s\S]*?<\/div>/gi, '')
    .trim();

  if (foundImage && !fullArticleHtml.includes(foundImage)) {
    fullArticleHtml = `<p><img src="${foundImage}" alt="" /></p>\n` + fullArticleHtml;
  }

  return {
    json: {
      ID: post.ID || post.id || null,
      post_title: post.post_title || post.title?.rendered || post.title || '',
      post_url: post.post_url || post.link || '',
      post_date: post.post_date || post.date || '',
      post_content: post.post_content || post.content || '',
      extracted_img_url: foundImage,
      all_html: fullArticleHtml
    }
  };
});

