const sheetItems = $input.all();
const js3Items = $('Vu-s').all();

function cleanTitleText(text) {
  if (!text) return "";
  return text.toString()
    .toLowerCase()
    .replace(/[^\w\s]/gi, '') // كيحيد جميع الرموز والنقاط والإيموجي
    .replace(/\s+/g, ' ')     // كيجمع الفراغات المتعددة في فراغ واحد
    .trim();
}

const titleToViewsMap = new Map();
for (const js3 of js3Items) {
  if (js3.json.title) {
    const cleaned = cleanTitleText(js3.json.title);
    titleToViewsMap.set(cleaned, js3.json.nodeValue);
  }
}

const newItems = [];
const processedTitles = new Set();

for (const item of sheetItems) {
  if (!item.json.title) continue;

  const cleanedSheetTitle = cleanTitleText(item.json.title);

  if (titleToViewsMap.has(cleanedSheetTitle) && !processedTitles.has(cleanedSheetTitle)) {
    processedTitles.add(cleanedSheetTitle);
    newItems.push({
      json: {
        row_number: item.json.row_number,
        id: item.json.id,
        title: item.json.title,
        image: item.json.image,
        comment: item.json.comment,
        nodeValue: titleToViewsMap.get(cleanedSheetTitle),
        postId: item.json.postId || null
      }
    });
  }
}

return newItems;

